"""
Juego Base - Nivel 1 (Python + tkinter, sin instalar nada extra)

Controles:
    Flechas izquierda/derecha  (o A / D)  -> moverse
    Espacio / Flecha arriba    (o W)      -> saltar
    R -> reiniciar        Esc -> salir

Objetivo: llegar al final del nivel y coger el muffin.
Si te caes por un hueco... pierdes.
Ejecutar:  python juego_base_v1.py
Pasar a Exe: python -m PyInstaller --onefile --windowed --name JuegoBase juego_base_v1.py

"""

import math
import random
import tkinter as tk

