TEXTO_GANA = "You Win! Te has desbucelado!"

# Trozos de suelo (inicio, fin). Los huecos entre ellos son abismos.
SUELOS = [(0, 1000), (1150, 2100), (2250, 3200), (3350, LARGO_NIVEL)]

# Plataformas flotantes y bloques: (x, y, ancho, alto)
PLATAFORMAS = [
    (400, 290, 120, 20), (620, 230, 110, 20), (820, 290, 100, 20),
    (2400, 290, 120, 20), (2620, 230, 120, 20), (2850, 290, 120, 20),
]
