# ----------------------------------------------------------------------
# Dibujo del muffin
# ----------------------------------------------------------------------
def dibujar_muffin(c, cx, by, s):
    """Dibuja un muffin con la base en (cx, by) y tamaño s."""
    grosor = max(1, int(2 * s))
    # Parte de arriba (el bizcocho)
    c.create_oval(cx - 32 * s, by - 70 * s, cx + 32 * s, by - 28 * s,
                  fill="#c98a4b", outline="#8a5a2b", width=grosor)
    # Trocitos de chocolate
    for dx, dy in [(-14, -55), (0, -62), (14, -54), (-4, -44), (20, -42), (-22, -42)]:
        c.create_oval(cx + (dx - 3) * s, by + (dy - 3) * s,
                      cx + (dx + 3) * s, by + (dy + 3) * s,
                      fill="#4a2c17", outline="")
    # Papelito
    c.create_polygon(cx - 24 * s, by - 38 * s, cx + 24 * s, by - 38 * s,
                     cx + 17 * s, by, cx - 17 * s, by,
                     fill="#f4a6c0", outline="#c9739a", width=grosor)
    for k in (-14, -5, 5, 14):
        c.create_line(cx + k * s, by - 38 * s, cx + k * 0.7 * s, by,
                      fill="#c9739a", width=max(1, int(s)))


# ----------------------------------------------------------------------
# El juego
# ----------------------------------------------------------------------
class Juego(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title("Marta grr - Nivel 1")
        self.resizable(False, False)
        self.c = tk.Canvas(self, width=ANCHO, height=ALTO, bg="#8ecae6",
                           highlightthickness=0)
        self.c.pack()

        # Imágenes (hay que guardarlas en self para que tkinter no las borre)
        self.img_pierde = tk.PhotoImage(data="".join(IMG_PIERDE_B64.split()))
        self.img_gana = tk.PhotoImage(data="".join(IMG_GANA_B64.split()))

        self.teclas = set()
        self.bind("<KeyPress>", self.tecla_abajo)
        self.bind("<KeyRelease>", self.tecla_arriba)
        self.focus_force()

        # Todo lo sólido contra lo que se puede chocar
        self.solidos = [(a, SUELO, b - a, 300) for a, b in SUELOS]
        self.solidos += PLATAFORMAS + BLOQUES

        self.nubes = [(100, 60), (420, 100), (700, 50), (980, 90), (1250, 55)]
        self.reiniciar()
        self.bucle()

    # ---------------- estado ----------------
    def reiniciar(self):
        self.x, self.y = 60.0, SUELO - JH
        self.vx = self.vy = 0.0
        self.dir = 1
        self.en_suelo = False
        self.gano = False
        self.perdio = False
        self.confeti = []
        self.frame = 0

    def tecla_abajo(self, e):
        k = e.keysym.lower()
        self.teclas.add(k)
        if k == "r":
            self.reiniciar()
        elif k == "escape":
            self.destroy()

    def tecla_arriba(self, e):
        self.teclas.discard(e.keysym.lower())

    # ---------------- bucle principal ----------------
    def bucle(self):
        self.frame += 1
        if self.gano:
            self.mover_confeti()
        elif not self.perdio:
            self.actualizar()
        self.dibujar()
        self.after(16, self.bucle)       # ~60 imágenes por segundo

    # ---------------- física ----------------
    def choca(self, r):
        return (self.x < r[0] + r[2] and self.x + JW > r[0] and
                self.y < r[1] + r[3] and self.y + JH > r[1])

    def actualizar(self):
        izq = bool(self.teclas & {"left", "a"})
        der = bool(self.teclas & {"right", "d"})
        salto = bool(self.teclas & {"space", "up", "w"})

        self.vx = 0
        if izq:
            self.vx -= VELOCIDAD
            self.dir = -1
        if der:
            self.vx += VELOCIDAD
            self.dir = 1
        if salto and self.en_suelo:
            self.vy = -SALTO

        # Movimiento horizontal
        self.x += self.vx
        self.x = max(0, min(self.x, LARGO_NIVEL - JW))
        for r in self.solidos:
            if self.choca(r):
                if self.vx > 0:
                    self.x = r[0] - JW
                elif self.vx < 0:
                    self.x = r[0] + r[2]

        # Movimiento vertical
        self.vy += GRAVEDAD
        self.y += self.vy
        self.en_suelo = False
        for r in self.solidos:
            if self.choca(r):
                if self.vy > 0:
                    self.y = r[1] - JH
                    self.en_suelo = True
                elif self.vy < 0:
                    self.y = r[1] + r[3]
                self.vy = 0

        # Si cae al abismo, pierde
        if self.y > ALTO + 80:
            self.perdio = True
            return

        # ¿Ha llegado al muffin?
        if self.choca((META_X - 25, SUELO - 65, 50, 65)):
            self.gano = True
            self.confeti = [[random.randint(0, ANCHO), random.randint(-400, 0),
                             random.uniform(2, 5), random.choice(COLORES_CONFETI),
                             random.randint(4, 8)] for _ in range(90)]

    def mover_confeti(self):
        for p in self.confeti:
            p[1] += p[2]
            if p[1] > ALTO:
                p[1] = -10
                p[0] = random.randint(0, ANCHO)

    # ---------------- dibujo ----------------
    def dibujar(self):
        c = self.c
        c.delete("all")
        cam = max(0, min(self.x - 300, LARGO_NIVEL - ANCHO))

        # Sol (fijo)
        c.create_oval(680, 30, 750, 100, fill="#ffd93d", outline="")

        # Nubes (se mueven despacio)
        for nx, ny in self.nubes:
            sx = (nx - cam * 0.3) % (ANCHO + 300) - 150
            c.create_oval(sx, ny, sx + 80, ny + 30, fill="white", outline="")
            c.create_oval(sx + 25, ny - 15, sx + 70, ny + 20, fill="white", outline="")

        # Colinas lejanas y cercanas (parallax)
        for i in range(-1, 6):
            hx = i * 400 - (cam * 0.4) % 400
            c.create_oval(hx, 300, hx + 480, 620, fill="#9bd39b", outline="")
        for i in range(-1, 6):
            hx = i * 330 - (cam * 0.65) % 330 + 120
            c.create_oval(hx, 340, hx + 380, 600, fill="#6fbf73", outline="")

        # Suelo
        for a, b in SUELOS:
            x1, x2 = a - cam, b - cam
            if x2 < 0 or x1 > ANCHO:
                continue
            c.create_rectangle(x1, SUELO, x2, ALTO, fill="#6b4a2b", outline="")
            c.create_rectangle(x1, SUELO, x2, SUELO + 12, fill="#4caf50", outline="")

        # Plataformas y bloques
        for x, y, w, h in PLATAFORMAS + BLOQUES:
            if x - cam > ANCHO or x + w - cam < 0:
                continue
            c.create_rectangle(x - cam, y, x + w - cam, y + h,
                               fill="#b5835a", outline="#6b4a2b", width=2)

        # Muffin de la meta (flota un poquito)
        flota = math.sin(self.frame * 0.1) * 3
        dibujar_muffin(c, META_X - cam, SUELO + flota, 1.0)

        # Jugador
        self.dibujar_monigote(self.x - cam, self.y)

        # Barra de progreso e instrucciones
        c.create_text(12, 12, anchor="nw", fill="#1d3557", font=("Arial", 10, "bold"),
                      text="← → mover   ·   Espacio saltar   ·   R reiniciar")
        c.create_rectangle(12, 34, 212, 42, outline="#1d3557", width=2)
        c.create_rectangle(12, 34, 12 + 200 * min(1, self.x / (META_X - 40)), 42,
                           fill="#e9573f", outline="")

        if self.gano:
            self.dibujar_victoria()
        elif self.perdio:
            self.dibujar_derrota()

    def dibujar_monigote(self, sx, sy):
        c = self.c
        cx = sx + JW / 2
        moviendose = self.en_suelo and bool(
            self.teclas & {"left", "right", "a", "d"})
        if self.en_suelo:
            fase = math.sin(self.frame * 0.35) * 10 if moviendose else 0
        else:
            fase = 12                       # piernas abiertas en el aire
        brazo = fase * 0.8 if self.en_suelo else -14

        # Nombre encima
        c.create_text(cx, sy - 16, text=NOMBRE, fill="#1d3557",
                      font=("Arial", 12, "bold"))
        # Cabeza, cuerpo, brazos, piernas
        c.create_oval(cx - 10, sy, cx + 10, sy + 20, fill="#ffe0bd",
                      outline="#222", width=3)
        c.create_oval(cx + self.dir * 4 - 2, sy + 7, cx + self.dir * 4 + 2, sy + 11,
                      fill="#222", outline="")
        c.create_line(cx, sy + 20, cx, sy + 42, fill="#222", width=3)
        c.create_line(cx, sy + 27, cx - brazo, sy + 38, fill="#222", width=3)
        c.create_line(cx, sy + 27, cx + brazo, sy + 38, fill="#222", width=3)
        c.create_line(cx, sy + 42, cx - fase, sy + JH, fill="#222", width=3)
        c.create_line(cx, sy + 42, cx + fase, sy + JH, fill="#222", width=3)

    def pantalla_final(self, imagen, texto, color_texto, color_sombra):
        """Oscurece el juego y muestra una imagen con una frase encima."""
        c = self.c
        c.create_rectangle(0, 0, ANCHO, ALTO, fill="black", stipple="gray50", outline="")
        c.create_text(ANCHO / 2 + 3, 48, text=texto, fill=color_sombra,
                      font=("Arial", 36, "bold"))
        c.create_text(ANCHO / 2, 45, text=texto, fill=color_texto,
                      font=("Arial", 36, "bold"))
        # marco blanco + imagen
        w, h = imagen.width(), imagen.height()
        cx, cy = ANCHO / 2, 85 + h / 2
        c.create_rectangle(cx - w / 2 - 5, cy - h / 2 - 5,
                           cx + w / 2 + 5, cy + h / 2 + 5,
                           fill="white", outline="")
        c.create_image(cx, cy, image=imagen)
        c.create_text(ANCHO / 2, ALTO - 20, fill="white", font=("Arial", 12),
                      text="R para jugar otra vez  ·  Esc para salir")

    def dibujar_victoria(self):
        c = self.c
        self.pantalla_final(self.img_gana, TEXTO_GANA, "#ffd93d", "#1d3557")
        for x, y, _, color, t in self.confeti:
            c.create_rectangle(x, y, x + t, y + t, fill=color, outline="")

    def dibujar_derrota(self):
        self.pantalla_final(self.img_pierde, TEXTO_PIERDE, "#ff6b6b", "#3b0a0a")


if __name__ == "__main__":
    Juego().mainloop()